<?php
$message='';if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$action=$_POST['action']??'';$pdo=db();if($action==='delete'){$pdo->prepare('DELETE FROM shop_products WHERE id=?')->execute([(int)$_POST['id']]);$message='محصول حذف شد.';}else{$data=[trim($_POST['name']),trim($_POST['category']),trim($_POST['description']),(int)$_POST['price'],trim($_POST['sizes']),max(0,(int)$_POST['stock']),trim($_POST['image']),trim($_POST['badge']),isset($_POST['featured'])?1:0];if(!empty($_POST['id'])){$data[]=(int)$_POST['id'];$pdo->prepare('UPDATE shop_products SET name=?,category=?,description=?,price=?,sizes=?,stock=?,image=?,badge=?,featured=? WHERE id=?')->execute($data);$message='محصول ویرایش شد.';}else{$pdo->prepare('INSERT INTO shop_products (name,category,description,price,sizes,stock,image,badge,featured,status,created_at) VALUES (?,?,?,?,?,?,?,?,?,1,UTC_TIMESTAMP())')->execute($data);$message='محصول اضافه شد.';}}}catch(Throwable $e){$message=$e->getMessage();}}
$edit=null;if(!empty($_GET['edit'])){$s=db()->prepare('SELECT * FROM shop_products WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$products=db()->query('SELECT * FROM shop_products ORDER BY id DESC')->fetchAll();page_header('مدیریت محصولات', 'admin');
?>
