="admin-list"><?php foreach($products as $p):?><div class="admin-row"><div class="admin-row-main"><img src="<?=url('assets/images/'.$p['image'])?>"><div><b><?=e($p['name'])?></b><span><?=money($p['price'])?> · موجودی <?=$p['stock']?></span></div></div><div><a class="btn" href="<?=url('admin/products?edit='.$p['id'])?>">ویرایش</a><form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="admin-delete">حذف</button></form></div></div><?php endforeach;?></div></div></div></div></section>
